function doubledAndMissing(nums: number[]): number[] {
  const n = nums.length;
  let diff = 0, diffSq = 0; // d - m and d^2 - m^2
  for (let i = 0; i < n; i++) {
    const v = i + 1;
    diff += nums[i] - v;
    diffSq += nums[i] * nums[i] - v * v;
  }
  const total = diffSq / diff; // d + m
  const d = (diff + total) / 2;
  return [d, d - diff];
}

